const fs=require('fs'),vm=require('vm'),assert=require('node:assert/strict');
class Element{
 constructor(dataset={}){this.dataset=dataset;this.attrs={};this.listeners={};this.hidden=true;this.textContent='';this.value='';this.valid=true;this.classList={add(){},remove(){}};}
 addEventListener(type,cb){this.listeners[type]=cb;}setAttribute(k,v){this.attrs[k]=v;}getAttribute(k){return this.attrs[k];}focus(){this.focused=true;}reportValidity(){return this.valid;}click(){this.listeners.click?.({target:this});}
}
const menu=new Element(),panel=new Element(),mobile=new Element(),shifts=['maya','alex','jules'].map(shift=>new Element({shift})),billing=['monthly','annual'].map(billing=>new Element({billing})),plans=['Free','Team','Business'].map(plan=>new Element({plan}));
menu.attrs['aria-expanded']='false';
const ids={};for(const id of ['handoff-avatar','handoff-name','handoff-from','handoff-copy','handoff-tag','handoff-incident','team-price','business-price','team-billing','business-billing','trial-form','trial-email','trial-status'])ids[id]=new Element();
ids['mobile-nav']=mobile;
const events={};const document={querySelector:s=>({'.menu-button':menu,'.handoff-panel':panel})[s],querySelectorAll:s=>({'[data-shift]':shifts,'[data-billing]':billing,'[data-plan]':plans})[s]||[],getElementById:id=>ids[id],addEventListener:(k,cb)=>events[k]=cb};
const window={matchMedia:()=>({matches:true,addEventListener(){}}),location:{href:''}};
vm.runInNewContext(fs.readFileSync('/tmp/rotaline-taste/script.js','utf8'),{document,window,encodeURIComponent});
menu.click();assert.equal(mobile.hidden,false);assert.equal(menu.attrs['aria-expanded'],'true');events.keydown({key:'Escape'});assert.equal(mobile.hidden,true);assert.equal(menu.focused,true);
menu.click();mobile.listeners.click({target:{closest:()=>true}});assert.equal(mobile.hidden,true);
billing[1].click();assert.equal(ids['team-price'].textContent,'"'$7'"');assert.equal(ids['business-price'].textContent,'"'$13'"');assert.equal(billing[1].attrs['aria-pressed'],'true');assert.equal(billing[0].attrs['aria-pressed'],'false');assert.match(ids['team-billing'].textContent,/84.*annually/);
billing[0].click();assert.equal(ids['team-price'].textContent,'"'$9'"');assert.equal(ids['business-price'].textContent,'"'$16'"');assert.equal(ids['business-billing'].textContent,'Billed monthly');
for(const [i,name]of ['Maya Chen','Alex Rivera','Jules Park'].entries()){shifts[i].click();assert.equal(ids['handoff-name'].textContent,name);assert.equal(shifts.filter(x=>x.attrs['aria-pressed']==='true').length,1);}
assert.equal(ids['handoff-tag'].textContent,'No open incidents');
ids['trial-email'].value='engineer@example.org';plans[2].click();billing[1].click();ids['trial-form'].listeners.submit({preventDefault(){}});assert.match(decodeURIComponent(window.location.href),/Plan: Business/);assert.match(decodeURIComponent(window.location.href),/Billing preference: annual/);assert.match(decodeURIComponent(window.location.href),/engineer@example.org/);assert.match(ids['trial-status'].textContent,/does not create an account/);
window.location.href='';ids['trial-email'].valid=false;ids['trial-form'].listeners.submit({preventDefault(){}});assert.equal(window.location.href,'');
console.log('PASS: menu opening, closing, Escape focus return, navigation selection, both billing modes and pressed states, all three handoffs, plan-aware email request, and invalid-email guard.');
JS"

